def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = 9

    # Create a new grid with original values (plus filled interiors)
    result = [[bg] * w for _ in range(h)]

    # Copy boundary shapes, leave interior as 9 for now
    for r in range(h):
        for c in range(w):
            result[r][c] = grid[r][c]

    # Mark all cells connected to edge (background-connected = not interior)
    marked_not_interior = [[False] * w for _ in range(h)]

    # Visited for finding connected components
    from collections import deque

    # Start from edge cells that are background
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg:
                edge = (r == 0 or r == h-1 or c == 0 or c == w-1)
                if edge:
                    marked_not_interior[r][c] = True

    # Also propagate from marked cells
    q = deque()
    for r in range(h):
        for c in range(w):
            if marked_not_interior[r][c]:
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if not marked_not_interior[nr][nc] and grid[nr][nc] == bg:
                    marked_not_interior[nr][nc] = True
                    q.append((nr, nc))

    # Find interior cells and their surrounding boundary color
    interior_cells = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and not marked_not_interior[r][c]:
                interior_cells.append((r, c))

    if not interior_cells:
        return result

    # For each interior cell, find a boundary (non-9) cell adjacent to it
    # We need to find which boundary color is "nearest" or same as any boundary cell
    # that can reach this interior cell

    for (r, c) in interior_cells:
        # BFS from this interior cell until we hit a non-9 cell
        visited_inside = [[False] * w for _ in range(h)]
        q = deque()
        q.append((r, c))
        visited_inside[r][c] = True
        found_boundary = False

        while q and not found_boundary:
            rr, cc = q.popleft()
            for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                nr, nc = rr + dr, cc + dc
                if 0 <= nr < h and 0 <= nc < w:
                    if grid[nr][nc] != bg:
                        found_boundary = True
                        boundary_color = grid[nr][nc]
